#ifndef CA_INTRO_H
#define CA_INTRO_H

// The Catalan intro text (LANG_CA=1), included by src/intro.c after its other headers.
// In the Spanish slot the intro types the Catalan texts of ca/intro_text.inc (generated by
// tools/genintro.py, with the letters tools/gfx_intro.py adds to intro/text_and_ship) and shows
// no subtitles, as the English intro does; the other languages are unchanged. Done by
// redefining the names src/intro.c uses, so the function bodies stay as in vanilla.
// CA_SELFTEST builds define nothing here, so the self-test stays byte-identical to vanilla.

#ifndef CA_SELFTEST

#include "types.h"
#include "constants/game_state.h"
#include "constants/intro.h"
#include "structs/game_state.h"

extern const u16 sCaIntroEmergencyOrderTextOam[];
extern const u16 sCaIntroExterminateAllTextOam[];
extern const u16 sCaIntroDefeatTheTextOam[];
extern const IntroTextAction sCaIntroEmergencyOrderActions[];
extern const IntroTextAction sCaIntroExterminateAllActions[];
extern const IntroTextAction sCaIntroDefeatTheActions[];
extern const u16 sCaIntroStartX[];
extern const u16 sCaIntroStartY[];

#define CA_INTRO_CATALAN (gLanguage == LANGUAGE_SPANISH)

// The typed texts (a macro's own name isn't expanded again inside it)
#define sIntroEmergencyOrderTextOam (CA_INTRO_CATALAN ? sCaIntroEmergencyOrderTextOam : sIntroEmergencyOrderTextOam)
#define sIntroExterminateAllTextOam (CA_INTRO_CATALAN ? sCaIntroExterminateAllTextOam : sIntroExterminateAllTextOam)
#define sIntroDefeatTheTextOam (CA_INTRO_CATALAN ? sCaIntroDefeatTheTextOam : sIntroDefeatTheTextOam)
#define sIntroEmergencyOrderActions (CA_INTRO_CATALAN ? sCaIntroEmergencyOrderActions : sIntroEmergencyOrderActions)
#define sIntroExterminateAllActions (CA_INTRO_CATALAN ? sCaIntroExterminateAllActions : sIntroExterminateAllActions)
#define sIntroDefeatTheActions (CA_INTRO_CATALAN ? sCaIntroDefeatTheActions : sIntroDefeatTheActions)

// No subtitles: the story text never starts, and reads as finished. Instead, on the first frame
// of each text (before any typing), the cursor moves to where the centred Catalan text starts.
#define CA_INTRO_PART(textId) ((textId) == STORY_TEXT_EMERGENCY ? 0 : (textId) == STORY_TEXT_EXTERMINATE ? 1 : 2)
#define TextStartStory(textId) do {                                  \
    if (!CA_INTRO_CATALAN)                                           \
        TextStartStory(textId);                                      \
    else                                                             \
    {                                                                \
        INTRO_DATA.charDrawerX = sCaIntroStartX[CA_INTRO_PART(textId)]; \
        INTRO_DATA.charDrawerY = sCaIntroStartY[CA_INTRO_PART(textId)]; \
    }                                                                \
} while (0)
#define TextProcessStory() (CA_INTRO_CATALAN ? TRUE : TextProcessStory())

#endif // !CA_SELFTEST

#endif // CA_INTRO_H
